const fs=require('fs'),vm=require('vm');const c={Engine:class{},motionReduced:false};vm.createContext(c);vm.runInContext(fs.readFileSync('assets/six-candy-rounds-engine.js','utf8')+'\nglobalThis.q={sixPickChanceRound,sixPickSugarRound,sixPickGapTemplate,sixMakeBoard,sixPlan,sixRoundClearBonus}',c);let seed=91237;const random=()=>((seed=(Math.imul(seed,1664525)+1013904223)>>>0)/4294967296);const q=c.q;let sum=0,sq=0,roles=0,bonus=0,clear=0;const N=1000;for(let k=0;k<N;k++){let chance=q.sixPickChanceRound(random),sugar=q.sixPickSugarRound(random),r=1,g;function board(){g=q.sixMakeBoard(10,chance===r?3:4,random,0,{holes:q.sixPickGapTemplate(random,r)}).grid;if(r===sugar){const a=g.flat().filter(t=>t&&t.number==null);a[Math.floor(random()*a.length)].sugar=true;}}board();const nums=Array.from({length:25},(_,i)=>i+1);for(let i=24;i>0;i--){let j=Math.floor(random()*(i+1));[nums[i],nums[j]]=[nums[j],nums[i]];}let total=0,pos=0;for(const n of [3,2,1,1,1]){let p=q.sixPlan(g,nums.slice(pos,pos+n));pos+=n;g=p.grid;total+=p.gain;roles+=p.gain-(p.cleared?10000:0);clear+=p.cleared?10000:0;if(p.advance){const b=q.sixRoundClearBonus(r);total+=b;bonus+=b;if(pos<8&&r<5){r++;board();}}}sum+=total;sq+=total*total;if((k+1)%100===0)console.log(k+1,sum/(k+1)/100);}console.log(JSON.stringify({N,mean:sum/N/100,se:Math.sqrt((sq/N-(sum/N)**2)/N)/100,roles:roles/N/100,bonus:bonus/N/100,clear:clear/N/100}));
